import React, { createContext, useContext, useState, useEffect, useCallback, useMemo } from 'react';
import { User, RequestCard, Status, Priority, Area, UserRole } from '../types';
import { AREA_HEADS } from '../constants';
import { db } from '../services/storage';
import { GoogleGenAI } from "@google/genai";

interface SisreqContextType {
  currentUser: User;
  users: User[];
  isAuthenticated: boolean;
  isLoading: boolean;
  login: (user: User) => void;
  logout: () => void;
  updateUser: (updatedUser: User) => Promise<void>;
  addUser: (name: string, email: string, role: UserRole, password: string, area?: Area) => Promise<void>;
  requests: RequestCard[];
  selectedRequestId: string | null;
  setSelectedRequestId: (id: string | null) => void;
  addRequest: (title: string, detail: string, area: Area, priority: Priority, requester: string) => Promise<void>;
  updateStatus: (id: string, newStatus: Status) => Promise<void>;
  returnRequest: (id: string, reason: string) => Promise<void>;
  assignAnalyst: (id: string, analystName: string) => Promise<void>;
  addLog: (id: string, message: string) => Promise<void>;
  updateRequestDetails: (id: string, title: string, detail: string) => Promise<void>;
  viewMode: 'work' | 'superadmin';
  setViewMode: (mode: 'work' | 'superadmin') => void;
  globalFilterArea: Area | 'ALL';
  setGlobalFilterArea: (area: Area | 'ALL') => void;
  canMoveRequest: (request: RequestCard, targetStatus: Status) => boolean;
  analyzeWithAI: (requestId: string) => Promise<string>;
}

const SisreqContext = createContext<SisreqContextType | undefined>(undefined);

export const SisreqProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [requests, setRequests] = useState<RequestCard[]>([]);
  const [selectedRequestId, setSelectedRequestId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'work' | 'superadmin'>('work');
  const [isLoading, setIsLoading] = useState(true);
  const [globalFilterArea, setGlobalFilterArea] = useState<Area | 'ALL'>('ALL');

  useEffect(() => {
    const init = async () => {
      await db.init();
      const [reqs, usrs] = await Promise.all([db.getRequests(), db.getUsers()]);
      setRequests(reqs);
      setUsers(usrs);
      setIsLoading(false);
    };
    init();
  }, []);

  const login = (user: User) => {
    const freshUser = users.find(u => u.id === user.id) || user;
    setCurrentUser(freshUser);
    setIsAuthenticated(true);
  };

  const logout = () => {
    setIsAuthenticated(false);
    setCurrentUser(null);
  };

  const analyzeWithAI = async (requestId: string): Promise<string> => {
    const req = requests.find(r => r.id === requestId);
    if (!req) return "Requerimiento no encontrado.";

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Analiza este requerimiento del sistema SISREQ y proporciona un resumen ejecutivo breve (máximo 3 líneas) y una sugerencia de acción inmediata.
        Título: ${req.title}
        Detalle: ${req.detail}
        Solicitante: ${req.requester}
        Prioridad: ${req.priority}`,
        config: {
            systemInstruction: "Eres un consultor experto en gestión de flujos de trabajo corporativos. Sé conciso y profesional."
        }
      });
      return response.text || "No se pudo generar el análisis.";
    } catch (error) {
      console.error("AI Analysis Error:", error);
      return "Error al conectar con el asistente de IA.";
    }
  };

  const canMoveRequest = useCallback((request: RequestCard, target: Status): boolean => {
    if (!currentUser) return false;
    if (currentUser.role === UserRole.SUPERADMIN) return true;

    const isOwnerArea = currentUser.area === request.area;
    const isAssignedToMe = request.assignedAnalyst === currentUser.name;

    const transitions: Record<UserRole, Partial<Record<Status, Status[]>>> = {
      [UserRole.SUPERADMIN]: {}, 
      [UserRole.ADMIN]: {
        [Status.RECIBIDO]: [Status.DERIVACION]
      },
      [UserRole.HEAD]: {
        [Status.DERIVACION]: isOwnerArea ? [Status.EJECUCION] : [],
        [Status.EJECUCION]: isOwnerArea ? [Status.FINALIZADO] : []
      },
      [UserRole.ANALYST]: {
        [Status.EJECUCION]: (isOwnerArea && isAssignedToMe) ? [Status.FINALIZADO] : []
      }
    };

    return transitions[currentUser.role]?.[request.status]?.includes(target) ?? false;
  }, [currentUser]);

  const updateRequestInStateAndDb = async (updated: RequestCard) => {
    setRequests(prev => prev.map(r => r.id === updated.id ? updated : r));
    await db.saveRequest(updated);
  };

  const updateStatus = async (id: string, newStatus: Status) => {
    const req = requests.find(r => r.id === id);
    if (!req || !canMoveRequest(req, newStatus)) return;

    const updated: RequestCard = { 
      ...req, 
      status: newStatus,
      isReturned: false,
      finishedAt: newStatus === Status.FINALIZADO ? new Date().toISOString() : req.finishedAt,
      assignedAnalyst: newStatus === Status.RECIBIDO ? undefined : req.assignedAnalyst,
      logs: [...req.logs, { id: `log-${Date.now()}`, timestamp: new Date().toISOString(), message: `Estado cambiado a: ${newStatus}`, actor: currentUser!.name }]
    };
    await updateRequestInStateAndDb(updated);
  };

  const returnRequest = async (id: string, reason: string) => {
    const req = requests.find(r => r.id === id);
    if (!req) return;
    const updated: RequestCard = {
      ...req, status: Status.RECIBIDO, isReturned: true, assignedAnalyst: undefined,
      logs: [...req.logs, { id: `log-${Date.now()}`, timestamp: new Date().toISOString(), message: `DEVUELTO: ${reason}`, actor: currentUser!.name }]
    };
    await updateRequestInStateAndDb(updated);
  };

  const assignAnalyst = async (id: string, analystName: string) => {
    const req = requests.find(r => r.id === id);
    if (!req) return;
    const updated: RequestCard = { 
        ...req, 
        assignedAnalyst: analystName, 
        logs: [...req.logs, { id: `log-${Date.now()}`, timestamp: new Date().toISOString(), message: `Asignado a: ${analystName}`, actor: currentUser!.name }] 
    };
    await updateRequestInStateAndDb(updated);
  };

  const addRequest = async (title: string, detail: string, area: Area, priority: Priority, requester: string) => {
    const newReq: RequestCard = {
      id: `req-${Date.now()}`, title, detail, area, priority, requester,
      status: Status.RECIBIDO, responsibleHead: AREA_HEADS[area], createdAt: new Date().toISOString(),
      logs: [{ id: `log-${Date.now()}`, timestamp: new Date().toISOString(), message: 'Requerimiento creado', actor: currentUser!.name }]
    };
    setRequests(prev => [...prev, newReq]);
    await db.saveRequest(newReq);
  };

  const addLog = async (id: string, message: string) => {
    const req = requests.find(r => r.id === id);
    if (!req) return;
    const updated: RequestCard = { 
      ...req, 
      logs: [...req.logs, { id: `log-${Date.now()}`, timestamp: new Date().toISOString(), message, actor: currentUser!.name }] 
    };
    await updateRequestInStateAndDb(updated);
  };

  const updateRequestDetails = async (id: string, title: string, detail: string) => {
    const req = requests.find(r => r.id === id);
    if (!req) return;
    const updated: RequestCard = { 
      ...req, title, detail, 
      logs: [...req.logs, { id: `log-${Date.now()}`, timestamp: new Date().toISOString(), message: 'Detalles del ticket actualizados', actor: currentUser!.name }] 
    };
    await updateRequestInStateAndDb(updated);
  };

  const updateUser = async (u: User) => {
    setUsers(prev => prev.map(old => old.id === u.id ? u : old));
    if (currentUser?.id === u.id) setCurrentUser(u);
    await db.saveUser(u);
  };

  const addUser = async (name: string, email: string, role: UserRole, password: string, area?: Area) => {
    const newUser: User = { id: `u-${Date.now()}`, name, email, role, area, password, status: 'ACTIVE', joinedAt: new Date().toISOString() };
    setUsers(prev => [...prev, newUser]);
    await db.saveUser(newUser);
  };

  const contextValue = useMemo(() => ({
    currentUser: currentUser!, users, isAuthenticated, isLoading, login, logout, updateUser, addUser,
    requests, selectedRequestId, setSelectedRequestId, addRequest, updateStatus, returnRequest,
    assignAnalyst, addLog, updateRequestDetails, viewMode, setViewMode, globalFilterArea, setGlobalFilterArea,
    canMoveRequest, analyzeWithAI
  }), [currentUser, users, isAuthenticated, isLoading, requests, selectedRequestId, viewMode, globalFilterArea, canMoveRequest]);

  return (
    <SisreqContext.Provider value={contextValue}>
      {children}
    </SisreqContext.Provider>
  );
};

export const useSisreq = () => {
  const context = useContext(SisreqContext);
  if (!context) throw new Error('useSisreq context error');
  return context;
};

import React, { useState, useEffect, useMemo } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { STATUS_BADGE_COLORS } from '../constants';
import { UserRole, Status } from '../types';
import { 
    X, User, Building, Clock, Tag, ArrowRight, 
    CheckCircle, Pencil, Save, Send, Sparkles, 
    Circle, BrainCircuit, Loader2
} from 'lucide-react';

export const RequestDetailModal: React.FC = () => {
  const { 
    selectedRequestId, setSelectedRequestId, requests, currentUser, 
    updateStatus, returnRequest, assignAnalyst, updateRequestDetails, addLog, users, canMoveRequest, analyzeWithAI
  } = useSisreq();

  const [returnReason, setReturnReason] = useState('');
  const [showReturnInput, setShowReturnInput] = useState(false);
  const [showAnalystSelect, setShowAnalystSelect] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editTitle, setEditTitle] = useState('');
  const [editDetail, setEditDetail] = useState('');
  const [newComment, setNewComment] = useState('');
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const data = useMemo(() => requests.find(r => r.id === selectedRequestId), [requests, selectedRequestId]);

  useEffect(() => {
     if (data) {
        setEditTitle(data.title);
        setEditDetail(data.detail);
        setIsEditing(false);
        setShowReturnInput(false);
        setShowAnalystSelect(false);
        setNewComment('');
        setAiAnalysis(null);
     }
  }, [selectedRequestId, data]);

  if (!selectedRequestId || !data) return null;

  const handleAiAnalyze = async () => {
    setIsAnalyzing(true);
    const result = await analyzeWithAI(data.id);
    setAiAnalysis(result);
    setIsAnalyzing(false);
  };

  const handleSaveEdit = () => {
    if (editTitle.trim() && editDetail.trim()) {
        updateRequestDetails(data.id, editTitle, editDetail);
        setIsEditing(false);
    }
  };

  const handleReturnSubmit = () => {
    if (returnReason.trim()) {
      returnRequest(data.id, returnReason);
      setShowReturnInput(false);
      setReturnReason('');
    }
  };

  const handleAddLog = () => {
    if (newComment.trim()) {
      addLog(data.id, `Nota: ${newComment}`);
      setNewComment('');
    }
  };

  const canEdit = currentUser.role === UserRole.SUPERADMIN || 
                  (currentUser.role === UserRole.ADMIN && data.status === Status.RECIBIDO) ||
                  ((currentUser.role === UserRole.HEAD || currentUser.role === UserRole.ANALYST) && data.area === currentUser.area);

  const availableAnalysts = users.filter(u => u.role === UserRole.ANALYST && u.area === data.area);

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-2 md:p-4">
      <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm transition-opacity" onClick={() => setSelectedRequestId(null)}></div>

      <div className="relative bg-white rounded-2xl shadow-2xl w-full max-w-5xl max-h-[95vh] flex flex-col overflow-hidden animate-in fade-in zoom-in-95 duration-200">

        {/* Header */}
        <div className="bg-slate-50 border-b px-4 md:px-8 py-4 md:py-6 flex justify-between items-start shrink-0">
            <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2 md:gap-3 mb-2 flex-wrap">
                    <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase shadow-sm ${STATUS_BADGE_COLORS[data.status]}`}>{data.status}</span>
                    <span className="text-[10px] text-slate-400 font-mono font-bold">#{data.id.split('-')[1]}</span>
                    {data.isReturned && <span className="bg-red-50 text-red-600 border border-red-100 px-2 py-0.5 rounded-full text-[10px] font-black">DEVUELTO</span>}
                    {!isEditing && canEdit && (
                         <button onClick={() => setIsEditing(true)} className="text-slate-400 hover:text-indigo-600 p-1 rounded-lg hover:bg-indigo-50 transition-colors"><Pencil size={14} /></button>
                    )}
                </div>
                {isEditing ? (
                    <input value={editTitle} onChange={(e) => setEditTitle(e.target.value)} className="w-full text-xl md:text-2xl font-black border-2 border-indigo-200 rounded-xl px-3 py-1.5 outline-none shadow-inner" autoFocus />
                ) : (
                    <h2 className="text-xl md:text-2xl font-black text-slate-800 tracking-tight" title={data.title}>{data.title}</h2>
                )}
            </div>
            <div className="flex gap-2 shrink-0 ml-4">
                {isEditing ? (
                    <button onClick={handleSaveEdit} className="px-4 py-2 bg-indigo-600 text-white rounded-xl text-xs font-black flex items-center gap-2 shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all"><Save size={14}/> Guardar</button>
                ) : (
                    <button onClick={() => setSelectedRequestId(null)} className="p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-100 border border-slate-200 rounded-full transition-all"><X size={20} /></button>
                )}
            </div>
        </div>

        {/* Body */}
        <div className="flex-1 overflow-hidden flex flex-col lg:flex-row">
            {/* Left Column: Details */}
            <div className="flex-1 overflow-y-auto custom-scrollbar p-4 md:p-8 space-y-8">

                {/* IA Insight Section */}
                <div className="bg-gradient-to-br from-indigo-50 to-blue-50 rounded-2xl border border-indigo-100 p-5 relative overflow-hidden group">
                    <div className="flex items-center justify-between mb-3 relative z-10">
                        <div className="flex items-center gap-2 text-indigo-700">
                            <BrainCircuit size={18} className="animate-pulse" />
                            <span className="text-xs font-black uppercase tracking-wider">Asistente IA SISREQ</span>
                        </div>
                        <button 
                            onClick={handleAiAnalyze}
                            disabled={isAnalyzing}
                            className="bg-white border border-indigo-200 text-indigo-600 px-3 py-1 rounded-lg text-[10px] font-black hover:bg-indigo-600 hover:text-white transition-all disabled:opacity-50 flex items-center gap-2 shadow-sm"
                        >
                            {isAnalyzing ? <Loader2 size={12} className="animate-spin" /> : <Sparkles size={12} />}
                            {aiAnalysis ? 'Actualizar Análisis' : 'Analizar Requerimiento'}
                        </button>
                    </div>

                    {aiAnalysis ? (
                        <div className="text-sm text-indigo-900/80 font-medium leading-relaxed animate-in fade-in slide-in-from-top-1">
                            {aiAnalysis}
                        </div>
                    ) : (
                        <div className="text-xs text-indigo-400 font-bold italic">
                            Pulsa el botón para obtener un resumen inteligente y sugerencias de gestión mediante IA.
                        </div>
                    )}

                    <div className="absolute -right-4 -bottom-4 opacity-5 text-indigo-600 group-hover:rotate-12 transition-transform">
                        <BrainCircuit size={100} />
                    </div>
                </div>

                <div className="space-y-3">
                    <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Tag size={14}/> Descripción del Caso</h3>
                    {isEditing ? (
                        <textarea value={editDetail} onChange={(e) => setEditDetail(e.target.value)} className="w-full h-40 bg-slate-50 border-2 border-indigo-100 rounded-2xl p-4 text-sm outline-none resize-none focus:border-indigo-400 transition-all shadow-inner" />
                    ) : (
                        <div className="bg-slate-50/50 p-6 rounded-2xl border border-slate-100 text-sm whitespace-pre-wrap text-slate-700 leading-relaxed font-medium">{data.detail}</div>
                    )}
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <div className="p-4 bg-white border border-slate-100 rounded-2xl shadow-sm group hover:border-indigo-200 transition-colors">
                        <span className="text-[10px] font-black text-slate-400 uppercase block mb-1">Unidad Solicitante</span>
                        <span className="text-sm font-black text-slate-800">{data.requester}</span>
                    </div>
                    <div className="p-4 bg-white border border-slate-100 rounded-2xl shadow-sm group hover:border-indigo-200 transition-colors">
                        <span className="text-[10px] font-black text-slate-400 uppercase block mb-1">Área Resolutiva</span>
                        <span className="text-sm font-black text-slate-800">{data.area}</span>
                    </div>
                </div>

                {data.assignedAnalyst && (
                     <div className="bg-slate-800 p-5 rounded-2xl flex items-center gap-4 transition-all shadow-xl shadow-slate-200">
                        <div className="w-12 h-12 rounded-full bg-indigo-600 flex items-center justify-center text-white text-lg font-black shadow-lg shadow-indigo-500/30 ring-4 ring-slate-700">{data.assignedAnalyst[0]}</div>
                        <div>
                            <div className="text-[10px] text-slate-400 font-black uppercase tracking-widest mb-0.5">Analista a Cargo</div>
                            <div className="text-md font-black text-white">{data.assignedAnalyst}</div>
                        </div>
                     </div>
                )}
            </div>

            {/* Right Column: Timeline */}
            <div className="w-full lg:w-96 bg-slate-50 border-t lg:border-t-0 lg:border-l flex flex-col h-[400px] lg:h-auto overflow-hidden">
                <div className="p-4 border-b bg-white shadow-sm z-10">
                    <div className="relative">
                        <textarea 
                            value={newComment} 
                            onChange={e => setNewComment(e.target.value)} 
                            className="w-full text-xs p-4 border-2 border-slate-100 rounded-2xl bg-slate-50 outline-none focus:ring-4 focus:ring-indigo-100 focus:bg-white focus:border-indigo-200 transition-all resize-none font-bold" 
                            placeholder="Escribe un comentario interno..." 
                            rows={3} 
                        />
                        <button onClick={handleAddLog} disabled={!newComment.trim()} className="absolute right-3 bottom-3 p-2 bg-indigo-600 text-white rounded-xl disabled:opacity-50 hover:bg-indigo-700 transition-all shadow-lg active:scale-95"><Send size={14}/></button>
                    </div>
                </div>

                <div className="flex-1 overflow-y-auto p-6 custom-scrollbar space-y-6">
                    <h3 className="text-[11px] font-black text-slate-400 uppercase flex items-center gap-2"><Clock size={14}/> Bitácora de Eventos</h3>
                    <div className="relative pl-3 border-l-2 border-slate-200 space-y-8">
                        {[...data.logs].reverse().map(log => (
                            <div key={log.id} className="relative pl-6">
                                <div className="absolute -left-[14px] top-0 w-6 h-6 rounded-full bg-white border-2 border-indigo-100 flex items-center justify-center shadow-sm">
                                    <Circle size={8} className="text-indigo-400 fill-indigo-400" />
                                </div>
                                <div className="flex justify-between items-center mb-1.5">
                                    <span className="text-[11px] font-black text-slate-800">{log.actor}</span>
                                    <span className="text-[10px] text-slate-400 font-black">{new Date(log.timestamp).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</span>
                                </div>
                                <div className="text-[11px] text-slate-600 bg-white p-3 rounded-xl border border-slate-100 shadow-sm leading-relaxed font-medium">
                                    {log.message}
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>

        {/* Actions Footer */}
        <div className="bg-white border-t p-4 md:p-6 flex items-center justify-between gap-4 shrink-0 shadow-[0_-8px_30px_rgba(0,0,0,0.04)]">
             <button onClick={() => setSelectedRequestId(null)} className="px-6 py-2 text-slate-400 hover:text-slate-600 font-black text-sm transition-colors">Cerrar</button>

             <div className="flex gap-3 flex-wrap justify-end">
                {/* Admin/SuperAdmin: Derivation */}
                {canMoveRequest(data, Status.DERIVACION) && (
                    <button onClick={() => updateStatus(data.id, Status.DERIVACION)} className="bg-orange-500 hover:bg-orange-600 text-white px-6 py-2.5 rounded-xl text-sm font-black shadow-xl shadow-orange-100 transition-all flex items-center gap-2 active:scale-95"><ArrowRight size={18}/> Derivar Área</button>
                )}

                {/* Head Actions */}
                {currentUser.role === UserRole.HEAD && data.area === currentUser.area && data.status === Status.DERIVACION && (
                    <>
                        <div className="relative">
                            <button onClick={() => setShowAnalystSelect(!showAnalystSelect)} className="bg-indigo-600 hover:bg-indigo-700 text-white px-6 py-2.5 rounded-xl text-sm font-black flex items-center gap-2 shadow-xl shadow-indigo-100 transition-all active:scale-95">
                                {data.assignedAnalyst ? 'Reasignar' : 'Asignar'} <User size={16}/>
                            </button>
                            {showAnalystSelect && (
                                <div className="absolute bottom-full right-0 mb-3 w-56 bg-white border border-slate-200 rounded-2xl shadow-2xl p-2 z-[80] animate-in slide-in-from-bottom-2 duration-200">
                                    <p className="text-[10px] font-black text-slate-400 uppercase p-3 border-b mb-1">Analistas Disponibles</p>
                                    <div className="max-h-48 overflow-y-auto custom-scrollbar">
                                        {availableAnalysts.length > 0 ? availableAnalysts.map(a => (
                                            <button key={a.id} onClick={() => { assignAnalyst(data.id, a.name); setShowAnalystSelect(false); }} className="w-full text-left p-3 hover:bg-indigo-50 rounded-xl text-xs font-black transition-colors text-slate-700 mb-1">{a.name}</button>
                                        )) : <p className="p-4 text-xs italic text-slate-400 font-bold">No hay analistas activos</p>}
                                    </div>
                                </div>
                            )}
                        </div>
                        <button onClick={() => updateStatus(data.id, Status.EJECUCION)} className="bg-amber-500 hover:bg-amber-600 text-white px-6 py-2.5 rounded-xl text-sm font-black transition-all shadow-xl shadow-amber-100 active:scale-95">Iniciar Ejecución</button>
                        <button onClick={() => setShowReturnInput(true)} className="text-red-500 hover:bg-red-50 px-6 py-2.5 text-sm font-black border-2 border-red-50 rounded-xl transition-all active:scale-95">Devolver</button>
                    </>
                )}

                {/* Finalize */}
                {canMoveRequest(data, Status.FINALIZADO) && (
                    <button onClick={() => updateStatus(data.id, Status.FINALIZADO)} className="bg-emerald-600 hover:bg-emerald-700 text-white px-8 py-2.5 rounded-xl text-sm font-black shadow-xl shadow-emerald-100 transition-all flex items-center gap-2 active:scale-95"><CheckCircle size={20}/> Finalizar Caso</button>
                )}
             </div>
        </div>

        {/* Portal Devolución */}
        {showReturnInput && (
            <div className="absolute inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-md animate-in fade-in duration-300">
                <div className="bg-white p-8 rounded-3xl shadow-[0_32px_64px_-12px_rgba(0,0,0,0.2)] w-full max-w-md border border-slate-100 mx-4">
                    <h4 className="text-xl font-black text-slate-800 mb-2">Devolver Requerimiento</h4>
                    <p className="text-xs text-slate-500 font-bold mb-6">Explique el motivo de la devolución. El ticket volverá a estado "Recibido".</p>
                    <textarea value={returnReason} onChange={e => setReturnReason(e.target.value)} className="w-full border-2 border-slate-100 p-4 rounded-2xl text-sm mb-6 outline-none focus:border-red-400 transition-all shadow-inner font-bold" placeholder="Ej: Información incompleta..." rows={4} autoFocus />
                    <div className="flex justify-end gap-3">
                        <button onClick={() => setShowReturnInput(false)} className="px-6 py-2 text-xs font-black text-slate-400 hover:text-slate-600">Cancelar</button>
                        <button onClick={handleReturnSubmit} disabled={!returnReason.trim()} className="bg-red-600 hover:bg-red-700 text-white px-8 py-3 rounded-xl text-xs font-black shadow-xl shadow-red-200 disabled:opacity-50 active:scale-95">Confirmar Devolución</button>
                    </div>
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { RequestCard } from './RequestCard';
import { Status, UserRole, Area } from '../types';
import { LayoutGrid, List, Search, Filter, Inbox, GitPullRequest, PlayCircle, CheckCircle2, Clock, Sparkles } from 'lucide-react';
import { STATUS_BADGE_COLORS } from '../constants';

export const Board: React.FC = () => {
  const { requests, currentUser, updateStatus, setSelectedRequestId, globalFilterArea, setGlobalFilterArea, canMoveRequest } = useSisreq();
  const [dragOverColumn, setDragOverColumn] = useState<Status | null>(null);
  const [viewMode, setViewMode] = useState<'board' | 'list'>('board');
  const [searchTerm, setSearchTerm] = useState('');

  const filteredRequests = useMemo(() => {
    return requests.filter(req => {
      const isAdmin = currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.SUPERADMIN;
      const isOwnerArea = req.area === currentUser.area && req.status !== Status.RECIBIDO;
      if (!isAdmin && !isOwnerArea) return false;

      const matchesSearch = searchTerm === '' || 
          req.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
          req.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
          req.requester.toLowerCase().includes(searchTerm.toLowerCase());

      const matchesArea = globalFilterArea === 'ALL' || req.area === globalFilterArea;
      return matchesSearch && matchesArea;
    });
  }, [requests, currentUser, searchTerm, globalFilterArea]);

  const handleDrop = (e: React.DragEvent, targetStatus: Status) => {
    e.preventDefault();
    setDragOverColumn(null);
    const requestId = e.dataTransfer.getData('requestId');
    const req = requests.find(r => r.id === requestId);
    if (req && canMoveRequest(req, targetStatus)) {
      updateStatus(requestId, targetStatus);
    }
  };

  const COLUMNS = [
    { title: 'Bandeja', status: Status.RECIBIDO, icon: <Inbox size={18} />, color: 'text-blue-700 bg-blue-50 border-blue-200 shadow-blue-100' },
    { title: 'Derivación', status: Status.DERIVACION, icon: <GitPullRequest size={18} />, color: 'text-orange-700 bg-orange-50 border-orange-200 shadow-orange-100' },
    { title: 'Ejecución', status: Status.EJECUCION, icon: <PlayCircle size={18} />, color: 'text-amber-700 bg-amber-50 border-amber-200 shadow-amber-100' },
    { title: 'Finalizado', status: Status.FINALIZADO, icon: <CheckCircle2 size={18} />, color: 'text-emerald-700 bg-emerald-50 border-emerald-200 shadow-emerald-100' }
  ];

  return (
    <div className="flex flex-col h-full overflow-hidden bg-slate-50/50">
      {/* Toolbar */}
      <div className="px-6 py-5 flex flex-col md:flex-row items-center justify-between gap-5 border-b bg-white/80 backdrop-blur-xl z-20 shrink-0 shadow-sm">
          <div className="flex items-center gap-6">
             <div className="flex items-center gap-3">
                <h2 className="text-xl font-black text-slate-800 tracking-tighter">Gestión Operativa</h2>
                <div className="bg-slate-800 text-white px-2.5 py-0.5 rounded-lg text-[10px] font-black shadow-lg shadow-slate-200">{filteredRequests.length}</div>
             </div>
             <div className="hidden lg:block w-px h-8 bg-slate-200"></div>
             <div className="flex bg-slate-100 p-1 rounded-xl border border-slate-200 shadow-inner items-center gap-1">
                <button onClick={() => setViewMode('board')} className={`p-2 rounded-lg transition-all ${viewMode === 'board' ? 'bg-white text-indigo-600 shadow-md' : 'text-slate-400 hover:text-slate-600'}`}><LayoutGrid size={16}/></button>
                <button onClick={() => setViewMode('list')} className={`p-2 rounded-lg transition-all ${viewMode === 'list' ? 'bg-white text-indigo-600 shadow-md' : 'text-slate-400 hover:text-slate-600'}`}><List size={16}/></button>
             </div>
          </div>

          <div className="flex flex-wrap items-center gap-4 w-full md:w-auto">
             <div className="relative group flex-1 md:flex-none">
                <Search size={16} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-indigo-500 transition-colors"/>
                <input 
                    type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Título, ID, solicitante..."
                    className="pl-11 pr-4 py-2.5 text-xs font-bold bg-white border-2 border-slate-100 rounded-xl focus:ring-4 focus:ring-indigo-100 focus:border-indigo-400 outline-none w-full md:w-72 transition-all shadow-sm"
                />
             </div>

             {(currentUser.role === UserRole.SUPERADMIN || currentUser.role === UserRole.ADMIN) && (
                <div className="relative">
                    <Filter size={14} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none"/>
                    <select
                        value={globalFilterArea} onChange={(e) => setGlobalFilterArea(e.target.value as Area | 'ALL')}
                        className="pl-10 pr-10 py-2.5 text-xs font-black border-2 border-slate-100 rounded-xl bg-white outline-none cursor-pointer hover:border-indigo-300 transition-all shadow-sm appearance-none"
                    >
                        <option value="ALL">Todas las Áreas</option>
                        {Object.values(Area).map(a => <option key={a} value={a}>{a}</option>)}
                    </select>
                </div>
             )}
          </div>
      </div>

      {/* Kanban / List Area */}
      <div className="flex-1 overflow-hidden">
        {viewMode === 'board' ? (
          <div className="h-full overflow-x-auto p-4 md:p-8 flex gap-8 snap-x snap-mandatory">
              {COLUMNS.map((col) => {
                  const items = filteredRequests.filter(r => r.status === col.status);
                  const isOver = dragOverColumn === col.status;
                  return (
                      <div 
                          key={col.status} 
                          className={`flex-1 flex flex-col min-w-[320px] max-w-[400px] rounded-3xl border-2 transition-all snap-center overflow-hidden shrink-0 ${isOver ? 'bg-indigo-50/50 border-indigo-400 border-dashed shadow-2xl scale-[1.02]' : 'bg-slate-50/40 border-transparent'}`}
                          onDragOver={(e) => { e.preventDefault(); setDragOverColumn(col.status); }}
                          onDragLeave={() => setDragOverColumn(null)}
                          onDrop={(e) => handleDrop(e, col.status)}
                      >
                          <div className={`flex items-center justify-between p-4 mx-3 mt-3 rounded-2xl border shadow-lg transition-all ${col.color}`}>
                              <div className="flex items-center gap-3 font-black text-xs uppercase tracking-widest">{col.icon} {col.title}</div>
                              <span className="bg-white/90 backdrop-blur-sm px-3 py-1 rounded-lg text-[10px] font-black shadow-sm ring-1 ring-black/5">{items.length}</span>
                          </div>

                          <div className="flex-1 overflow-y-auto custom-scrollbar px-3 pb-12 pt-4 flex flex-col gap-4">
                              {items.length === 0 ? (
                                  <div className={`flex-1 min-h-[200px] flex flex-col items-center justify-center text-slate-300 border-4 border-dashed rounded-3xl transition-all m-2 ${isOver ? 'border-indigo-200 bg-indigo-50/40 text-indigo-400' : 'border-slate-100/50'}`}>
                                      {isOver ? <Sparkles size={48} className="mb-3 animate-bounce"/> : <Inbox size={48} className="mb-3 opacity-10"/>}
                                      <span className="text-[10px] font-black uppercase tracking-[0.2em]">{isOver ? 'Soltar aquí' : 'Sin pendientes'}</span>
                                  </div>
                              ) : (
                                  <>
                                    {items.map(req => <RequestCard key={req.id} data={req} />)}
                                    <div className="flex-1 min-h-[60px] opacity-0">Bottom Spacer</div>
                                  </>
                              )}
                          </div>
                      </div>
                  )
              })}
          </div>
        ) : (
            <div className="h-full overflow-auto p-4 md:p-8">
                <div className="bg-white rounded-3xl border-2 border-slate-100 shadow-2xl overflow-hidden">
                    <table className="w-full text-left text-sm border-collapse">
                        <thead className="bg-slate-50 border-b text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">
                            <tr>
                                <th className="px-8 py-5">Identificador</th>
                                <th className="px-8 py-5">Título del Requerimiento</th>
                                <th className="px-8 py-5">Área Destino</th>
                                <th className="px-8 py-5">Prioridad</th>
                                <th className="px-8 py-5">Estado Actual</th>
                                <th className="px-8 py-5 text-right">Solicitante</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {filteredRequests.map(req => (
                                <tr key={req.id} onClick={() => setSelectedRequestId(req.id)} className="hover:bg-indigo-50/50 cursor-pointer transition-all group">
                                    <td className="px-8 py-5 font-mono text-xs text-slate-400 group-hover:text-indigo-600 font-bold">#{req.id.split('-')[1]}</td>
                                    <td className="px-8 py-5">
                                        <div className="font-black text-slate-800 group-hover:text-indigo-900 transition-colors text-sm">{req.title}</div>
                                        <div className="text-[10px] text-slate-400 flex items-center gap-2 mt-1 font-bold"><Clock size={12}/> {new Date(req.createdAt).toLocaleDateString()}</div>
                                    </td>
                                    <td className="px-8 py-5 text-xs font-black text-slate-500 uppercase tracking-tight">{req.area}</td>
                                    <td className="px-8 py-5">
                                        <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase ${req.priority === 'Alta' ? 'bg-red-100 text-red-600 shadow-sm shadow-red-50' : 'bg-slate-100 text-slate-500'}`}>{req.priority}</span>
                                    </td>
                                    <td className="px-8 py-5">
                                        <span className={`px-4 py-1.5 rounded-xl text-[10px] font-black uppercase shadow-sm ${STATUS_BADGE_COLORS[req.status]}`}>{req.status}</span>
                                    </td>
                                    <td className="px-8 py-5 text-slate-700 text-xs font-black text-right">{req.requester}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                    {filteredRequests.length === 0 && (
                        <div className="p-24 text-center flex flex-col items-center gap-4">
                             <div className="bg-slate-50 p-6 rounded-full">
                                <Search size={48} className="text-slate-200"/>
                             </div>
                             <div>
                                <p className="text-slate-800 font-black text-lg">Sin resultados</p>
                                <p className="text-slate-400 font-bold text-sm">No encontramos requerimientos con esos criterios.</p>
                             </div>
                        </div>
                    )}
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { Status, Area, Priority } from '../types';
import { 
    BarChart3, TrendingUp, CheckCircle2, Clock, 
    Activity, AlertTriangle, CalendarRange, ArrowRight,
    Briefcase, Zap, Layers
} from 'lucide-react';

export const ReportsView: React.FC = () => {
  const { requests, users, setViewMode, setGlobalFilterArea } = useSisreq();
  const [timeRange, setTimeRange] = useState<'Semanal' | 'Mensual' | 'Anual' | 'Todo'>('Mensual');

  const filteredRequests = useMemo(() => {
    if (timeRange === 'Todo') return requests;
    const now = new Date();
    return requests.filter(r => {
        const reqDate = new Date(r.createdAt);
        const diffTime = Math.abs(now.getTime() - reqDate.getTime());
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
        if (timeRange === 'Semanal') return diffDays <= 7;
        if (timeRange === 'Mensual') return diffDays <= 30;
        if (timeRange === 'Anual') return diffDays <= 365;
        return true;
    });
  }, [requests, timeRange]);

  const stats = useMemo(() => {
    const total = filteredRequests.length;
    const completed = filteredRequests.filter(r => r.status === Status.FINALIZADO).length;
    const pending = total - completed;
    const completionRate = total > 0 ? Math.round((completed / total) * 100) : 0;

    const byStatus = [Status.RECIBIDO, Status.DERIVACION, Status.EJECUCION, Status.FINALIZADO].map(status => {
        const count = filteredRequests.filter(r => r.status === status).length;
        const percentage = total > 0 ? Math.round((count / total) * 100) : 0;
        return { name: status, count, percentage };
    });

    const byArea = Object.values(Area).map(area => {
        const count = filteredRequests.filter(r => r.area === area).length;
        return { name: area, count, total };
    }).sort((a, b) => b.count - a.count);

    const byPriority = Object.values(Priority).map(p => ({
        name: p,
        count: filteredRequests.filter(r => r.priority === p).length
    }));

    const completedItems = filteredRequests.filter(r => r.status === Status.FINALIZADO && r.finishedAt);
    let avgDays = 0;
    if (completedItems.length > 0) {
        const totalMs = completedItems.reduce((acc, curr) => {
            const start = new Date(curr.createdAt).getTime();
            const end = new Date(curr.finishedAt!).getTime();
            return acc + (end - start);
        }, 0);
        avgDays = Math.round(totalMs / (1000 * 60 * 60 * 24) / completedItems.length);
    }

    const analystCounts: Record<string, number> = {};
    filteredRequests.forEach(r => {
        if (r.assignedAnalyst) {
            analystCounts[r.assignedAnalyst] = (analystCounts[r.assignedAnalyst] || 0) + 1;
        }
    });

    const topAnalysts = Object.entries(analystCounts)
        .map(([name, count]) => ({ name, count }))
        .sort((a, b) => b.count - a.count)
        .slice(0, 3);

    return { total, completed, pending, completionRate, byStatus, byArea, byPriority, avgDays, topAnalysts };
  }, [filteredRequests]);

  const handleViewDetails = () => {
    setGlobalFilterArea('ALL');
    setViewMode('work');
  };

  return (
    <div className="flex-1 overflow-y-auto custom-scrollbar p-6 md:p-10 space-y-10 bg-slate-50/50">

        {/* Title Section */}
        <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
            <div>
                <h2 className="text-3xl font-black text-slate-800 tracking-tight flex items-center gap-3">
                    <BarChart3 className="text-indigo-600" size={32} /> Analítica SISREQ
                </h2>
                <p className="text-slate-500 text-sm font-bold mt-2">
                    Métricas de rendimiento operativo: <span className="text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded-md">{timeRange}</span>
                </p>
            </div>

            <div className="flex bg-white p-1.5 rounded-2xl border-2 border-slate-100 shadow-xl shadow-slate-200/50">
                {['Semanal', 'Mensual', 'Anual', 'Todo'].map((range) => (
                    <button
                        key={range}
                        onClick={() => setTimeRange(range as any)}
                        className={`px-5 py-2 text-xs font-black rounded-xl transition-all ${
                            timeRange === range 
                            ? 'bg-slate-800 text-white shadow-lg' 
                            : 'text-slate-400 hover:bg-slate-50 hover:text-slate-700'
                        }`}
                    >
                        {range}
                    </button>
                ))}
            </div>
        </div>

        {/* KPIs */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            {[
                { label: 'Total Requerimientos', val: stats.total, sub: '+5% vs mes anterior', icon: <Briefcase size={20}/>, grad: 'from-indigo-500 to-blue-600', shadow: 'shadow-indigo-100' },
                { label: 'En Proceso', val: stats.pending, sub: `${stats.byStatus[2].count} ejecutándose`, icon: <Zap size={20}/>, grad: 'from-amber-400 to-orange-500', shadow: 'shadow-amber-100' },
                { label: 'Tasa Finalización', val: `${stats.completionRate}%`, sub: 'Meta: 85%', icon: <CheckCircle2 size={20}/>, grad: 'from-emerald-400 to-teal-500', shadow: 'shadow-emerald-100' },
                { label: 'Tiempo Promedio', val: `${stats.avgDays} d`, sub: 'Objetivo: < 5 días', icon: <Clock size={20}/>, grad: 'from-blue-400 to-indigo-500', shadow: 'shadow-blue-100' }
            ].map((kpi, i) => (
                <div key={i} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-2xl shadow-slate-200/40 hover:-translate-y-1 transition-all duration-300 relative overflow-hidden group">
                    <div className="absolute -top-4 -right-4 p-8 opacity-5 group-hover:opacity-10 transition-opacity">
                         <div className="scale-[4]">{kpi.icon}</div>
                    </div>
                    <div className="relative z-10 space-y-4">
                        <div className={`w-12 h-12 bg-gradient-to-br ${kpi.grad} text-white rounded-2xl flex items-center justify-center shadow-lg ${kpi.shadow}`}>
                            {kpi.icon}
                        </div>
                        <div>
                            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.15em] mb-1">{kpi.label}</p>
                            <p className="text-3xl font-black text-slate-800 tracking-tighter">{kpi.val}</p>
                        </div>
                        <div className="text-[10px] font-black text-indigo-500 bg-indigo-50 w-fit px-2 py-1 rounded-lg">
                            {kpi.sub}
                        </div>
                    </div>
                </div>
            ))}
        </div>

        {/* Charts Row */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="lg:col-span-2 bg-white rounded-3xl shadow-2xl shadow-slate-200/40 border border-slate-100 p-8 md:p-10">
                <div className="flex items-center justify-between mb-10">
                    <h3 className="font-black text-slate-800 text-lg flex items-center gap-3">
                        <ArrowRight size={24} className="text-indigo-500"/> Pipeline de Operaciones
                    </h3>
                </div>

                <div className="space-y-8">
                    {stats.byStatus.map((step, idx) => (
                        <div key={step.name}>
                            <div className="flex justify-between items-end mb-3">
                                <div className="flex items-center gap-4">
                                    <div className={`w-8 h-8 rounded-xl flex items-center justify-center text-xs font-black border-2 ${
                                        step.count > 0 ? 'bg-slate-800 border-slate-800 text-white' : 'bg-white border-slate-200 text-slate-300'
                                    }`}>
                                        0{idx + 1}
                                    </div>
                                    <span className="text-sm font-black text-slate-700 tracking-tight">{step.name}</span>
                                </div>
                                <div className="text-right">
                                    <span className="text-sm font-black text-slate-800">{step.count}</span>
                                    <span className="text-[10px] font-bold text-slate-400 ml-2">({step.percentage}%)</span>
                                </div>
                            </div>
                            <div className="w-full h-5 bg-slate-50 rounded-2xl overflow-hidden shadow-inner border border-slate-100 p-1">
                                <div 
                                    className={`h-full rounded-xl transition-all duration-1000 ease-out relative overflow-hidden ${
                                        step.name === Status.FINALIZADO ? 'bg-emerald-500' : 
                                        step.name === Status.EJECUCION ? 'bg-amber-400' :
                                        'bg-indigo-500'
                                    }`}
                                    style={{ width: `${Math.max(step.percentage, 2)}%` }}
                                >
                                    <div className="absolute inset-0 opacity-10" style={{backgroundImage: 'linear-gradient(45deg,rgba(255,255,255,.2) 25%,transparent 25%,transparent 50%,rgba(255,255,255,.2) 50%,rgba(255,255,255,.2) 75%,transparent 75%,transparent)', backgroundSize: '1.5rem 1.5rem'}}></div>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            <div className="bg-white rounded-3xl shadow-2xl shadow-slate-200/40 border border-slate-100 p-8 md:p-10 flex flex-col">
                <h3 className="font-black text-slate-800 text-lg mb-8 flex items-center gap-3">
                    <AlertTriangle size={24} className="text-amber-500"/> Criticidad
                </h3>

                <div className="flex-1 flex items-end justify-between gap-6 px-4">
                    {stats.byPriority.map((p) => {
                         const height = stats.total > 0 ? (p.count / stats.total) * 100 : 0;
                         return (
                            <div key={p.name} className="flex flex-col items-center gap-4 flex-1 h-60 justify-end group">
                                <div className="text-xl font-black text-slate-800 opacity-0 group-hover:opacity-100 transition-all -translate-y-4 group-hover:translate-y-0 duration-300">
                                    {p.count}
                                </div>
                                <div className="w-full relative flex items-end justify-center h-full">
                                    <div 
                                        className={`w-full max-w-[64px] rounded-2xl transition-all duration-1000 shadow-xl ${
                                            p.name === 'Alta' ? 'bg-red-500 shadow-red-200' : 
                                            p.name === 'Media' ? 'bg-amber-400 shadow-amber-200' : 
                                            'bg-slate-300 shadow-slate-100'
