                                </div>
                                <div className="text-[10px] font-black uppercase tracking-widest text-slate-500 group-hover:text-slate-800 transition-colors">
                                    {p.name}
                                </div>
                            </div>
                         );
                    })}
                </div>
            </div>
        </div>

        {/* Load Section */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 pb-10">
            <div className="bg-white rounded-3xl shadow-2xl shadow-slate-200/40 border border-slate-100 p-8">
                <div className="flex justify-between items-center mb-10">
                    <h3 className="font-black text-slate-800 text-lg flex items-center gap-3">
