            </div>

            <div className="bg-slate-900 rounded-3xl shadow-2xl p-8 flex flex-col">
                <h3 className="font-black text-white text-lg mb-10 flex items-center gap-3">
                    <Zap size={24} className="text-yellow-400 animate-pulse"/> Analistas Estrella
                </h3>
                <div className="space-y-5">
                    {stats.topAnalysts.map((analyst, idx) => (
                        <div key={analyst.name} className="flex items-center gap-5 p-4 rounded-2xl bg-slate-800/50 hover:bg-slate-800 transition-all border border-slate-700/50 group">
                            <div className={`w-10 h-10 flex items-center justify-center font-black text-sm rounded-xl shadow-lg ${
                                idx === 0 ? 'bg-yellow-400 text-yellow-900 ring-4 ring-yellow-400/20' : 
                                idx === 1 ? 'bg-slate-400 text-slate-900' : 
                                'bg-orange-500 text-white'
                            }`}>
                                {idx + 1}
                            </div>
                            <div className="flex-1">
                                <div className="font-black text-white text-sm tracking-tight">{analyst.name}</div>
                                <div className="text-[10px] text-slate-400 font-bold uppercase">{users.find(u => u.name === analyst.name)?.area || 'Unidad de Apoyo'}</div>
                            </div>
                            <div className="text-right">
                                <div className="text-xl font-black text-white leading-none">{analyst.count}</div>
                                <div className="text-[9px] text-slate-500 font-black uppercase tracking-tighter">Resueltos</div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { UserRole, User } from '../types';
import { LayoutDashboard, User as UserIcon, Shield, Briefcase, KeyRound, LogIn, ChevronDown, Check, Fingerprint } from 'lucide-react';

const getRoleLabel = (role: UserRole) => {
  switch (role) {
      case UserRole.SUPERADMIN: return 'Super Admin';
      case UserRole.ADMIN: return 'Administración';
      case UserRole.HEAD: return 'Jefaturas';
      default: return 'Analistas';
  }
};

interface UserItemProps {
  user: User;
  isSelected: boolean;
  onSelect: (user: User) => void;
}

const UserItem: React.FC<UserItemProps> = ({ user, isSelected, onSelect }) => (
    <button 
      type="button"
      onClick={() => onSelect(user)}
      className="w-full flex items-center gap-4 p-4 hover:bg-indigo-50 transition-all text-left group border-b border-slate-50 last:border-0"
    >
      <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-black text-xs transition-all shadow-sm ${
          user.role === UserRole.SUPERADMIN ? 'bg-slate-800 text-white shadow-slate-200' :
          user.role === UserRole.ADMIN ? 'bg-red-50 text-red-600 group-hover:bg-red-100 shadow-red-50' :
          user.role === UserRole.HEAD ? 'bg-indigo-50 text-indigo-600 group-hover:bg-indigo-100 shadow-indigo-50' :
          'bg-slate-100 text-slate-600 group-hover:bg-slate-200'
      }`}>
          {user.name.substring(0, 2).toUpperCase()}
      </div>
      <div className="flex-1 min-w-0">
          <div className="text-sm font-black text-slate-800 group-hover:text-indigo-800 truncate tracking-tight">{user.name}</div>
          <div className="text-[10px] text-slate-500 font-bold uppercase truncate tracking-wider">{user.area || getRoleLabel(user.role)}</div>
      </div>
      {isSelected && <div className="bg-indigo-600 p-1 rounded-full"><Check size={14} className="text-white"/></div>}
    </button>
);

export const LoginPage: React.FC = () => {
  const { login, users } = useSisreq();
  const [selectedUser, setSelectedUser] = useState<User | null>(null);
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const superAdminUsers = users.filter(u => u.role === UserRole.SUPERADMIN);
  const adminUsers = users.filter(u => u.role === UserRole.ADMIN);
  const headUsers = users.filter(u => u.role === UserRole.HEAD);
  const analystUsers = users.filter(u => u.role === UserRole.ANALYST);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedUser) return;
    if (password === selectedUser.password || password === '1234') {
        login(selectedUser);
    } else {
        setError('Acceso denegado: Contraseña incorrecta');
        setPassword('');
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 relative overflow-hidden">

        {/* Abstract Background Decoration */}
        <div className="absolute top-0 left-0 w-full h-full opacity-[0.03] pointer-events-none select-none">
             <div className="absolute top-20 left-10 text-indigo-600 rotate-12 scale-[15]"><Fingerprint /></div>
             <div className="absolute bottom-20 right-10 text-indigo-600 -rotate-12 scale-[15]"><Shield /></div>
        </div>

        {/* Logo Section */}
        <div className="mb-12 text-center animate-in fade-in slide-in-from-bottom-8 duration-700 relative z-10">
            <div className="inline-flex items-center gap-4 mb-4 bg-white p-5 rounded-3xl shadow-2xl border border-slate-100">
                <div className="bg-gradient-to-br from-indigo-600 to-blue-700 p-3 rounded-2xl shadow-xl shadow-indigo-200">
                    <LayoutDashboard className="text-white" size={32} />
                </div>
                <div className="text-left">
                    <h1 className="text-3xl font-black tracking-tighter text-slate-800 leading-none">SISREQ</h1>
                    <p className="text-[10px] text-slate-400 font-black uppercase tracking-[0.2em] mt-1">SISTEMA DE GESTIÓN</p>
                </div>
            </div>
            <p className="text-slate-500 text-sm font-bold max-w-xs mx-auto">Control y trazabilidad absoluta para requerimientos interdepartamentales.</p>
        </div>

        <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-[0_40px_80px_-20px_rgba(0,0,0,0.12)] border border-slate-100 p-10 animate-in zoom-in-95 duration-500 relative z-10 overflow-visible">

            <form onSubmit={handleLogin} className="space-y-8">

                {/* Dropdown Usuario */}
                <div className="space-y-3" ref={dropdownRef}>
                    <label className="block text-[11px] font-black text-slate-400 uppercase tracking-widest pl-1">Identidad de Acceso</label>
                    <div className="relative">
                        <button
                            type="button"
                            onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                            className={`w-full bg-slate-50 border-2 ${isDropdownOpen ? 'border-indigo-500 ring-8 ring-indigo-50' : 'border-slate-100 hover:border-slate-200'} rounded-2xl p-4 flex items-center justify-between transition-all outline-none`}
                        >
                            {selectedUser ? (
                                <div className="flex items-center gap-4 min-w-0">
                                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-black text-xs flex-shrink-0 shadow-sm ${
                                        selectedUser.role === UserRole.SUPERADMIN ? 'bg-slate-800 text-white' :
                                        selectedUser.role === UserRole.ADMIN ? 'bg-red-500 text-white' :
                                        selectedUser.role === UserRole.HEAD ? 'bg-indigo-600 text-white' :
                                        'bg-slate-400 text-white'
                                    }`}>
                                        {selectedUser.name.substring(0, 2).toUpperCase()}
                                    </div>
                                    <div className="text-left min-w-0">
                                        <div className="text-sm font-black text-slate-800 truncate">{selectedUser.name}</div>
                                        <div className="text-[10px] text-slate-500 font-bold uppercase truncate tracking-wider">{selectedUser.area || getRoleLabel(selectedUser.role)}</div>
                                    </div>
                                </div>
                            ) : (
                                <span className="text-slate-400 text-sm pl-2 font-bold italic">Seleccione su cuenta profesional...</span>
                            )}
                            <ChevronDown size={20} className={`text-slate-300 transition-transform flex-shrink-0 ${isDropdownOpen ? 'rotate-180 text-indigo-500' : ''}`}/>
                        </button>

                        {isDropdownOpen && (
                            <div className="absolute top-full left-0 right-0 mt-4 bg-white rounded-3xl shadow-[0_30px_60px_-15px_rgba(0,0,0,0.3)] border border-slate-100 z-[100] max-h-72 overflow-y-auto custom-scrollbar animate-in fade-in slide-in-from-top-4 duration-200">
                                {superAdminUsers.length > 0 && (
                                    <>
                                        <div className="sticky top-0 bg-slate-50/90 backdrop-blur-md px-5 py-3 border-b border-slate-100 text-[10px] font-black text-slate-500 uppercase z-10 flex items-center gap-3">
                                            <Shield size={12} /> Gestión de Infraestructura
                                        </div>
                                        {superAdminUsers.map(u => <UserItem key={u.id} user={u} isSelected={selectedUser?.id === u.id} onSelect={(u) => {setSelectedUser(u); setIsDropdownOpen(false); setPassword(''); setError('');}} />)}
                                    </>
                                )}
                                <div className="sticky top-0 bg-slate-50/90 backdrop-blur-md px-5 py-3 border-y border-slate-100 text-[10px] font-black text-slate-500 uppercase z-10 flex items-center gap-3">
                                    <Fingerprint size={12} /> Administración Central
                                </div>
                                {adminUsers.map(u => <UserItem key={u.id} user={u} isSelected={selectedUser?.id === u.id} onSelect={(u) => {setSelectedUser(u); setIsDropdownOpen(false); setPassword(''); setError('');}} />)}
                                <div className="sticky top-0 bg-slate-50/90 backdrop-blur-md px-5 py-3 border-y border-slate-100 text-[10px] font-black text-slate-500 uppercase z-10 flex items-center gap-3">
                                    <Briefcase size={12} /> Jefaturas de Área
                                </div>
                                {headUsers.map(u => <UserItem key={u.id} user={u} isSelected={selectedUser?.id === u.id} onSelect={(u) => {setSelectedUser(u); setIsDropdownOpen(false); setPassword(''); setError('');}} />)}
                                <div className="sticky top-0 bg-slate-50/90 backdrop-blur-md px-5 py-3 border-y border-slate-100 text-[10px] font-black text-slate-500 uppercase z-10 flex items-center gap-3">
                                    <UserIcon size={12} /> Equipo de Análisis
                                </div>
                                {analystUsers.map(u => <UserItem key={u.id} user={u} isSelected={selectedUser?.id === u.id} onSelect={(u) => {setSelectedUser(u); setIsDropdownOpen(false); setPassword(''); setError('');}} />)}
                            </div>
                        )}
                    </div>
                </div>

                {selectedUser && (
                    <div className="space-y-6 animate-in slide-in-from-top-4 fade-in duration-300">
                        <div className="space-y-3">
                            <label className="block text-[11px] font-black text-slate-400 uppercase tracking-widest pl-1">Llave de Seguridad</label>
                            <div className="relative group">
                                <KeyRound className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-indigo-500 transition-colors" size={20}/>
                                <input 
                                    type="password" 
                                    autoFocus
                                    value={password}
                                    onChange={(e) => setPassword(e.target.value)}
                                    className="w-full pl-12 pr-6 py-4 bg-slate-50 rounded-2xl border-2 border-slate-100 focus:ring-8 focus:ring-indigo-50 focus:border-indigo-400 outline-none transition-all font-black placeholder:text-slate-300 placeholder:italic"
                                    placeholder="Ingrese PIN de acceso..."
                                />
                            </div>
                        </div>

                        {error && (
                            <div className="bg-red-50 text-red-600 p-4 rounded-2xl text-[11px] font-black flex items-center gap-3 animate-in shake border-2 border-red-100">
                                <Shield size={16}/> {error}
                            </div>
                        )}

                        <button 
                            type="submit"
                            className="w-full bg-slate-900 hover:bg-black text-white font-black py-5 rounded-3xl shadow-2xl shadow-slate-200 hover:shadow-indigo-100 transition-all active:scale-95 flex items-center justify-center gap-3 text-sm tracking-widest border-2 border-slate-900"
                        >
                            <LogIn size={20}/> AUTENTICAR
                        </button>
                    </div>
                )}
            </form>

            <div className="mt-10 text-center flex flex-col items-center gap-2">
                <div className="h-px w-full bg-slate-50 mb-2"></div>
                <span className="text-[10px] text-slate-400 font-black uppercase tracking-[0.2em]">Entorno de Demostración</span>
                <span className="text-[11px] font-black text-indigo-600 bg-indigo-50 px-4 py-1.5 rounded-full">PIN: 1234</span>
            </div>
        </div>
    </div>
  );
};

